/// Look up a zone's TZif bytes by IANA name (e.g. "America/Santiago").
pub fn find(name: []const u8) ?[]const u8 {
    var lo: usize = 0;
    var hi: usize = all_zones.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        switch (std.mem.order(u8, all_zones[mid].name, name)) {
            .lt => lo = mid + 1,
            .gt => hi = mid,
            .eq => return all_zones[mid].data,
        }
    }
    return null;
}

